-- SessionBridge schema version 1.
--
-- IDs are UUID strings generated by the application. Timestamps are Unix
-- microseconds. JSON columns are validated at the storage boundary.

CREATE TABLE workspaces (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    repository_identity TEXT NOT NULL UNIQUE CHECK (length(repository_identity) > 0),
    created_at INTEGER NOT NULL
);

CREATE TABLE tasks (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    workspace_id TEXT NOT NULL,
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    phase TEXT NOT NULL CHECK (phase IN ('active', 'paused', 'completed', 'cancelled', 'archived')),
    autonomy_policy TEXT NOT NULL CHECK (autonomy_policy IN ('manual', 'proposal', 'bounded', 'open')),
    completion_policy TEXT NOT NULL CHECK (completion_policy IN ('all_workers_concluded')),
    target_branch TEXT,
    plan_version INTEGER NOT NULL DEFAULT 0 CHECK (plan_version >= 0),
    completion_epoch INTEGER NOT NULL DEFAULT 1 CHECK (completion_epoch >= 1),
    completion_revision INTEGER NOT NULL DEFAULT 0 CHECK (completion_revision >= 0),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    paused_at INTEGER,
    completed_at INTEGER,
    cancelled_at INTEGER,
    archived_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT,
    UNIQUE (id, workspace_id)
);

CREATE INDEX idx_tasks_workspace_phase ON tasks(workspace_id, phase);

CREATE TABLE task_criteria (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('objective', 'constraint', 'non_goal', 'done_condition')),
    content TEXT NOT NULL CHECK (length(trim(content)) > 0),
    required INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),
    source TEXT NOT NULL CHECK (source IN ('user', 'system')),
    evaluation_mode TEXT NOT NULL CHECK (evaluation_mode IN ('positive_evidence', 'continuous_guard')),
    immutable_to_agents INTEGER NOT NULL DEFAULT 1 CHECK (immutable_to_agents IN (0, 1)),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (id, task_id)
);

CREATE INDEX idx_task_criteria_task_kind ON task_criteria(task_id, kind);

CREATE TABLE criterion_coverage (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    criterion_id TEXT NOT NULL,
    covered_by_type TEXT NOT NULL CHECK (covered_by_type IN ('requirement', 'evidence')),
    covered_by_id TEXT NOT NULL CHECK (length(covered_by_id) > 0),
    status TEXT NOT NULL CHECK (status IN ('covered', 'verified', 'invalidated')),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (criterion_id, task_id) REFERENCES task_criteria(id, task_id) ON DELETE CASCADE,
    UNIQUE (criterion_id, covered_by_type, covered_by_id)
);

CREATE INDEX idx_criterion_coverage_task_status ON criterion_coverage(task_id, status);

CREATE TABLE requirements (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (length(kind) > 0),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    description TEXT NOT NULL DEFAULT '',
    required INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),
    status TEXT NOT NULL CHECK (status IN ('proposed', 'active', 'superseded', 'rejected')),
    source TEXT NOT NULL CHECK (source IN ('user', 'agent', 'system')),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (id, task_id)
);

CREATE INDEX idx_requirements_task_status ON requirements(task_id, status, required);

CREATE TABLE requirement_coverage (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    requirement_id TEXT NOT NULL,
    covered_by_type TEXT NOT NULL CHECK (covered_by_type IN ('work_item', 'artifact', 'evidence')),
    covered_by_id TEXT NOT NULL CHECK (length(covered_by_id) > 0),
    coverage_state TEXT NOT NULL CHECK (coverage_state IN ('uncovered', 'planned', 'implemented', 'verified', 'integrated')),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (requirement_id, task_id) REFERENCES requirements(id, task_id) ON DELETE CASCADE,
    UNIQUE (requirement_id, covered_by_type, covered_by_id)
);

CREATE INDEX idx_requirement_coverage_task_state ON requirement_coverage(task_id, coverage_state);

CREATE TABLE agent_sessions (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    token_hash BLOB NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    label TEXT NOT NULL CHECK (length(trim(label)) > 0),
    client_name TEXT,
    model TEXT,
    declared_capabilities_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(declared_capabilities_json)),
    capacity_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(capacity_json)),
    worktree_path TEXT,
    branch TEXT,
    base_commit TEXT,
    head_commit TEXT,
    target_branch TEXT,
    protocol_version INTEGER NOT NULL CHECK (protocol_version >= 1),
    last_seen_at INTEGER NOT NULL,
    ended_at INTEGER,
    end_reason TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK ((ended_at IS NULL AND end_reason IS NULL) OR ended_at IS NOT NULL)
);

CREATE INDEX idx_agent_sessions_task_ended ON agent_sessions(task_id, ended_at, last_seen_at);

CREATE TABLE agent_invitations (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    completion_epoch INTEGER NOT NULL CHECK (completion_epoch >= 1),
    participant_kind TEXT NOT NULL CHECK (participant_kind IN ('worker', 'observer')),
    batch_id TEXT NOT NULL CHECK (length(batch_id) > 0),
    token_hash BLOB NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    state TEXT NOT NULL CHECK (state IN ('prepared', 'pending', 'reserved', 'consumed', 'revoked', 'expired', 'abandoned')),
    blocks_completion INTEGER NOT NULL CHECK (blocks_completion IN (0, 1)),
    capability_limits_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(capability_limits_json)),
    prepare_request_id TEXT,
    prepare_expires_at INTEGER,
    reserved_by_request_id TEXT,
    reservation_expires_at INTEGER,
    prompt_template_version INTEGER NOT NULL CHECK (prompt_template_version >= 1),
    protocol_version INTEGER NOT NULL CHECK (protocol_version >= 1),
    expires_at INTEGER NOT NULL,
    revoked_at INTEGER,
    consumed_at INTEGER,
    consumed_by_session_id TEXT,
    rotates_from_id TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (consumed_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (rotates_from_id, task_id) REFERENCES agent_invitations(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    UNIQUE (rotates_from_id),
    CHECK ((participant_kind = 'worker' AND blocks_completion = 1) OR (participant_kind = 'observer' AND blocks_completion = 0)),
    CHECK (state <> 'prepared' OR (prepare_request_id IS NOT NULL AND prepare_expires_at IS NOT NULL)),
    CHECK (state <> 'reserved' OR (reserved_by_request_id IS NOT NULL AND reservation_expires_at IS NOT NULL)),
    CHECK (state <> 'consumed' OR (consumed_at IS NOT NULL AND consumed_by_session_id IS NOT NULL)),
    CHECK (state <> 'revoked' OR revoked_at IS NOT NULL)
);

CREATE UNIQUE INDEX uq_agent_invitations_active_reservation_request
    ON agent_invitations(reserved_by_request_id)
    WHERE state = 'reserved' AND reserved_by_request_id IS NOT NULL;
CREATE INDEX idx_agent_invitations_completion_cohort
    ON agent_invitations(task_id, completion_epoch, blocks_completion, state, expires_at);
CREATE INDEX idx_agent_invitations_prepare_batch
    ON agent_invitations(batch_id, prepare_request_id, state);

CREATE TABLE task_participants (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    invitation_id TEXT,
    kind TEXT NOT NULL CHECK (kind IN ('worker', 'observer')),
    completion_epoch INTEGER NOT NULL CHECK (completion_epoch >= 1),
    state TEXT NOT NULL CHECK (state IN ('active', 'waiting', 'concluded', 'blocked', 'departed', 'retired', 'superseded')),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    current_conclusion_id TEXT,
    joined_at INTEGER NOT NULL,
    departed_at INTEGER,
    retired_at INTEGER,
    superseded_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (invitation_id, task_id) REFERENCES agent_invitations(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (current_conclusion_id) REFERENCES agent_conclusions(id) DEFERRABLE INITIALLY DEFERRED,
    UNIQUE (id, task_id),
    UNIQUE (task_id, session_id, completion_epoch),
    UNIQUE (invitation_id),
    CHECK ((state IN ('concluded', 'blocked') AND current_conclusion_id IS NOT NULL) OR
           (state NOT IN ('concluded', 'blocked') AND current_conclusion_id IS NULL)),
    CHECK (state <> 'departed' OR departed_at IS NOT NULL),
    CHECK (state <> 'retired' OR retired_at IS NOT NULL),
    CHECK (state <> 'superseded' OR superseded_at IS NOT NULL)
);

CREATE INDEX idx_task_participants_cohort
    ON task_participants(task_id, completion_epoch, kind, state);
CREATE INDEX idx_task_participants_session
    ON task_participants(session_id, state);

CREATE TABLE capability_grants (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    capability TEXT NOT NULL CHECK (length(capability) > 0),
    issuer_type TEXT NOT NULL CHECK (issuer_type IN ('user', 'system', 'session', 'invitation')),
    issuer_id TEXT,
    scope_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(scope_json)),
    expires_at INTEGER,
    revoked_at INTEGER,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE CASCADE
);

CREATE INDEX idx_capability_grants_active
    ON capability_grants(task_id, session_id, capability, expires_at, revoked_at);

CREATE TABLE agent_conclusions (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    participant_id TEXT NOT NULL,
    generation INTEGER NOT NULL CHECK (generation >= 1),
    outcome TEXT NOT NULL CHECK (outcome IN ('no_further_work', 'blocked')),
    basis_completion_revision INTEGER NOT NULL CHECK (basis_completion_revision >= 0),
    basis_event_cursor INTEGER NOT NULL CHECK (basis_event_cursor >= 0),
    basis_plan_version INTEGER NOT NULL CHECK (basis_plan_version >= 0),
    assessment_schema_version INTEGER NOT NULL CHECK (assessment_schema_version >= 1),
    assessment_json TEXT NOT NULL CHECK (json_valid(assessment_json)),
    signal_snapshot_json TEXT NOT NULL CHECK (json_valid(signal_snapshot_json)),
    warning_snapshot_json TEXT NOT NULL CHECK (json_valid(warning_snapshot_json)),
    created_at INTEGER NOT NULL,
    FOREIGN KEY (participant_id, task_id) REFERENCES task_participants(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    UNIQUE (participant_id, generation)
);

CREATE INDEX idx_agent_conclusions_task_participant
    ON agent_conclusions(task_id, participant_id, generation);

CREATE TRIGGER validate_task_participant_current_conclusion_insert
BEFORE INSERT ON task_participants
WHEN NEW.current_conclusion_id IS NOT NULL
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM agent_conclusions c
        WHERE c.id = NEW.current_conclusion_id
          AND c.participant_id = NEW.id
          AND ((NEW.state = 'concluded' AND c.outcome = 'no_further_work') OR
               (NEW.state = 'blocked' AND c.outcome = 'blocked'))
    ) THEN RAISE(ABORT, 'current conclusion does not match participant state') END;
END;

CREATE TRIGGER validate_task_participant_current_conclusion_update
BEFORE UPDATE OF state, current_conclusion_id ON task_participants
WHEN NEW.current_conclusion_id IS NOT NULL
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1
        FROM agent_conclusions c
        WHERE c.id = NEW.current_conclusion_id
          AND c.participant_id = NEW.id
          AND ((NEW.state = 'concluded' AND c.outcome = 'no_further_work') OR
               (NEW.state = 'blocked' AND c.outcome = 'blocked'))
    ) THEN RAISE(ABORT, 'current conclusion does not match participant state') END;
END;

CREATE TRIGGER agent_conclusions_immutable_update
BEFORE UPDATE ON agent_conclusions
BEGIN
    SELECT RAISE(ABORT, 'agent conclusions are immutable');
END;

CREATE TRIGGER agent_conclusions_immutable_delete
BEFORE DELETE ON agent_conclusions
BEGIN
    SELECT RAISE(ABORT, 'agent conclusions are immutable');
END;

CREATE TABLE evidence (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    attempt_id TEXT,
    artifact_id TEXT,
    kind TEXT NOT NULL CHECK (length(kind) > 0),
    result TEXT NOT NULL CHECK (result IN ('passed', 'failed', 'inconclusive')),
    details_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(details_json)),
    created_by_session_id TEXT,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id)
);

CREATE TABLE participant_retirements (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    participant_id TEXT NOT NULL,
    proposer_participant_id TEXT NOT NULL,
    reason TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    handoff_json TEXT NOT NULL CHECK (json_valid(handoff_json)),
    status TEXT NOT NULL CHECK (status IN ('proposed', 'pending_approval', 'approved', 'applied', 'rejected', 'cancelled')),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    applied_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (participant_id, task_id) REFERENCES task_participants(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (proposer_participant_id, task_id) REFERENCES task_participants(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK (participant_id <> proposer_participant_id),
    CHECK (status <> 'applied' OR applied_at IS NOT NULL)
);

CREATE UNIQUE INDEX uq_participant_retirements_open
    ON participant_retirements(participant_id)
    WHERE status IN ('proposed', 'pending_approval', 'approved');

CREATE TABLE participant_retirement_evidence (
    participant_retirement_id TEXT NOT NULL,
    evidence_id TEXT NOT NULL,
    PRIMARY KEY (participant_retirement_id, evidence_id),
    FOREIGN KEY (participant_retirement_id) REFERENCES participant_retirements(id) ON DELETE CASCADE,
    FOREIGN KEY (evidence_id) REFERENCES evidence(id) ON DELETE RESTRICT
);

CREATE TABLE gaps (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (length(kind) > 0),
    severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    required INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),
    dedupe_key TEXT,
    status TEXT NOT NULL CHECK (status IN ('open', 'resolved', 'superseded', 'rejected')),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    description TEXT NOT NULL DEFAULT '',
    reported_by_session_id TEXT,
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    resolved_at INTEGER,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (reported_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id)
);

CREATE UNIQUE INDEX uq_gaps_open_dedupe
    ON gaps(task_id, dedupe_key)
    WHERE dedupe_key IS NOT NULL AND status = 'open';
CREATE INDEX idx_gaps_task_status ON gaps(task_id, status, required, severity);

CREATE TABLE role_profiles (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    workspace_id TEXT NOT NULL,
    slug TEXT NOT NULL CHECK (length(trim(slug)) > 0),
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    instructions TEXT NOT NULL DEFAULT '',
    capabilities_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(capabilities_json)),
    allowed_scopes_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(allowed_scopes_json)),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
    UNIQUE (workspace_id, slug)
);

CREATE TABLE work_items (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    parent_id TEXT,
    kind TEXT NOT NULL CHECK (kind IN ('discovery', 'design', 'contract', 'implementation', 'verification', 'documentation', 'coordination')),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    description TEXT NOT NULL DEFAULT '',
    required INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),
    priority INTEGER NOT NULL DEFAULT 0,
    risk TEXT NOT NULL CHECK (risk IN ('low', 'medium', 'high', 'critical')),
    required_capabilities_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(required_capabilities_json)),
    acceptance_criteria_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(acceptance_criteria_json)),
    expected_artifacts_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(expected_artifacts_json)),
    planned_resources_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(planned_resources_json)),
    plan_state TEXT NOT NULL CHECK (plan_state IN ('proposed', 'active', 'superseded', 'cancelled')),
    result_state TEXT NOT NULL CHECK (result_state IN ('open', 'submitted', 'accepted')),
    created_by_session_id TEXT,
    dedupe_key TEXT,
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    submitted_at INTEGER,
    accepted_at INTEGER,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (parent_id, task_id) REFERENCES work_items(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (created_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK (parent_id IS NULL OR parent_id <> id)
);

CREATE UNIQUE INDEX uq_work_items_active_dedupe
    ON work_items(task_id, dedupe_key)
    WHERE dedupe_key IS NOT NULL AND plan_state IN ('proposed', 'active');
CREATE INDEX idx_work_items_task_state ON work_items(task_id, plan_state, result_state, priority DESC);
CREATE INDEX idx_work_items_parent ON work_items(task_id, parent_id);

CREATE TABLE work_relations (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    from_id TEXT NOT NULL,
    to_id TEXT NOT NULL,
    relation_type TEXT NOT NULL CHECK (relation_type IN ('depends_on', 'duplicates', 'supersedes')),
    created_by_session_id TEXT,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (from_id, task_id) REFERENCES work_items(id, task_id) ON DELETE CASCADE,
    FOREIGN KEY (to_id, task_id) REFERENCES work_items(id, task_id) ON DELETE CASCADE,
    FOREIGN KEY (created_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (task_id, from_id, to_id, relation_type),
    CHECK (from_id <> to_id)
);

CREATE INDEX idx_work_relations_from ON work_relations(task_id, from_id, relation_type);
CREATE INDEX idx_work_relations_to ON work_relations(task_id, to_id, relation_type);

CREATE TABLE plan_changes (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    proposer_session_id TEXT NOT NULL,
    base_plan_version INTEGER NOT NULL CHECK (base_plan_version >= 0),
    operations_json TEXT NOT NULL CHECK (json_valid(operations_json)),
    risk_class TEXT NOT NULL CHECK (risk_class IN ('safe', 'high')),
    status TEXT NOT NULL CHECK (status IN ('proposed', 'pending_approval', 'applied', 'rejected', 'superseded')),
    reason TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    applied_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (proposer_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK (status <> 'applied' OR applied_at IS NOT NULL)
);

CREATE INDEX idx_plan_changes_task_status ON plan_changes(task_id, status, created_at);

CREATE TABLE work_claims (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    work_item_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    mode TEXT NOT NULL CHECK (mode IN ('execute', 'review', 'integrate')),
    generation INTEGER NOT NULL CHECK (generation >= 1),
    claimed_at INTEGER NOT NULL,
    lease_expires_at INTEGER NOT NULL,
    renewed_at INTEGER,
    closed_at INTEGER,
    close_reason TEXT CHECK (close_reason IS NULL OR close_reason IN ('submitted', 'released', 'yielded', 'abandoned', 'revoked', 'reclaimed')),
    FOREIGN KEY (work_item_id, task_id) REFERENCES work_items(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    UNIQUE (work_item_id, mode, generation),
    CHECK ((closed_at IS NULL AND close_reason IS NULL) OR closed_at IS NOT NULL)
);

CREATE UNIQUE INDEX uq_work_claims_active_execute
    ON work_claims(work_item_id)
    WHERE mode = 'execute' AND closed_at IS NULL;
CREATE UNIQUE INDEX uq_work_claims_active_mode_per_session
    ON work_claims(work_item_id, session_id, mode)
    WHERE closed_at IS NULL;
CREATE INDEX idx_work_claims_session_active ON work_claims(session_id, closed_at, lease_expires_at);
CREATE INDEX idx_work_claims_item_active ON work_claims(work_item_id, mode, closed_at, lease_expires_at);

CREATE TABLE work_attempts (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    claim_id TEXT NOT NULL UNIQUE,
    work_item_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    base_plan_version INTEGER NOT NULL CHECK (base_plan_version >= 0),
    base_commit TEXT,
    status TEXT NOT NULL CHECK (status IN ('active', 'submitted', 'abandoned', 'lost', 'superseded', 'reclaimed')),
    started_at INTEGER NOT NULL,
    ended_at INTEGER,
    FOREIGN KEY (claim_id, task_id) REFERENCES work_claims(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (work_item_id, task_id) REFERENCES work_items(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK ((status = 'active' AND ended_at IS NULL) OR status <> 'active')
);

CREATE INDEX idx_work_attempts_item_status ON work_attempts(work_item_id, status, started_at);

CREATE TABLE attempt_input_pins (
    attempt_id TEXT NOT NULL,
    input_type TEXT NOT NULL CHECK (input_type IN ('work_item', 'contract', 'artifact', 'change_set', 'target_branch')),
    input_id TEXT NOT NULL CHECK (length(input_id) > 0),
    revision_or_digest TEXT NOT NULL CHECK (length(revision_or_digest) > 0),
    created_at INTEGER NOT NULL,
    PRIMARY KEY (attempt_id, input_type, input_id),
    FOREIGN KEY (attempt_id) REFERENCES work_attempts(id) ON DELETE CASCADE
);

CREATE TABLE agent_intents (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    participant_id TEXT,
    kind TEXT NOT NULL CHECK (kind IN ('explore', 'plan', 'implement', 'review', 'integrate')),
    target_type TEXT NOT NULL CHECK (length(target_type) > 0),
    target_id TEXT,
    summary TEXT NOT NULL CHECK (length(trim(summary)) > 0),
    expected_outputs_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(expected_outputs_json)),
    expires_at INTEGER NOT NULL,
    cleared_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE CASCADE,
    FOREIGN KEY (participant_id, task_id) REFERENCES task_participants(id, task_id) ON DELETE CASCADE,
    UNIQUE (id, task_id)
);

CREATE INDEX idx_agent_intents_active ON agent_intents(task_id, session_id, cleared_at, expires_at);

CREATE TABLE resource_reservations (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    owner_type TEXT NOT NULL CHECK (owner_type IN ('claim', 'change_set')),
    owner_id TEXT NOT NULL CHECK (length(owner_id) > 0),
    resource_key TEXT NOT NULL CHECK (length(resource_key) > 0),
    mode TEXT NOT NULL CHECK (mode IN ('read', 'write', 'exclusive')),
    policy TEXT NOT NULL CHECK (policy IN ('enforced', 'advisory')),
    pinned_revision TEXT,
    released_at INTEGER,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (owner_type, owner_id, resource_key)
);

CREATE INDEX idx_resource_reservations_active
    ON resource_reservations(task_id, resource_key, mode, policy, released_at);

CREATE TABLE resource_usage (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    attempt_id TEXT NOT NULL,
    resource_key TEXT NOT NULL CHECK (length(resource_key) > 0),
    mode TEXT NOT NULL CHECK (mode IN ('read', 'write')),
    observed_revision TEXT,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (attempt_id, task_id) REFERENCES work_attempts(id, task_id) ON DELETE CASCADE,
    UNIQUE (attempt_id, resource_key, mode)
);

CREATE TABLE contracts (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    kind TEXT NOT NULL CHECK (kind IN ('api', 'schema', 'file_format', 'behavior', 'build')),
    owner_type TEXT NOT NULL CHECK (owner_type IN ('task', 'work_item', 'session')),
    owner_id TEXT NOT NULL CHECK (length(owner_id) > 0),
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (id, task_id),
    UNIQUE (task_id, name)
);

CREATE TABLE contract_revisions (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    contract_id TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    state TEXT NOT NULL CHECK (state IN ('draft', 'published', 'accepted', 'superseded', 'rejected')),
    digest TEXT NOT NULL CHECK (length(digest) > 0),
    compatibility TEXT NOT NULL CHECK (compatibility IN ('compatible', 'breaking', 'unknown')),
    content_json TEXT NOT NULL CHECK (json_valid(content_json)),
    created_by_session_id TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    FOREIGN KEY (contract_id, task_id) REFERENCES contracts(id, task_id) ON DELETE CASCADE,
    FOREIGN KEY (created_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (contract_id, revision),
    UNIQUE (id, task_id)
);

CREATE TABLE work_item_contract_requirements (
    work_item_id TEXT NOT NULL,
    contract_id TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision >= 1),
    requirement_type TEXT NOT NULL CHECK (requirement_type IN ('exact', 'minimum', 'compatible')),
    created_at INTEGER NOT NULL,
    PRIMARY KEY (work_item_id, contract_id, revision, requirement_type),
    FOREIGN KEY (work_item_id) REFERENCES work_items(id) ON DELETE CASCADE,
    FOREIGN KEY (contract_id, revision) REFERENCES contract_revisions(contract_id, revision) ON DELETE RESTRICT
);

CREATE TABLE decisions (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    topic TEXT NOT NULL CHECK (length(trim(topic)) > 0),
    proposal_json TEXT NOT NULL CHECK (json_valid(proposal_json)),
    status TEXT NOT NULL CHECK (status IN ('proposed', 'pending_approval', 'accepted', 'rejected', 'superseded')),
    supersedes_id TEXT,
    proposed_by_session_id TEXT NOT NULL,
    version INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (supersedes_id, task_id) REFERENCES decisions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (proposed_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK (supersedes_id IS NULL OR supersedes_id <> id)
);

CREATE TABLE approvals (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    target_type TEXT NOT NULL CHECK (target_type IN ('plan_change', 'decision', 'participant_retirement', 'task_reopen')),
    target_id TEXT NOT NULL CHECK (length(target_id) > 0),
    session_id TEXT NOT NULL,
    decision TEXT NOT NULL CHECK (decision IN ('approved', 'rejected')),
    created_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (target_type, target_id, session_id)
);

CREATE TABLE coordination_requests (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('question', 'review', 'unblock', 'decision', 'integration', 'handoff')),
    target_type TEXT NOT NULL CHECK (length(target_type) > 0),
    target_id TEXT,
    requested_by_session_id TEXT NOT NULL,
    assigned_session_id TEXT,
    required_capability TEXT,
    blocking INTEGER NOT NULL DEFAULT 0 CHECK (blocking IN (0, 1)),
    status TEXT NOT NULL CHECK (status IN ('open', 'acknowledged', 'resolved', 'cancelled')),
    correlation_id TEXT,
    payload_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload_json)),
    response_json TEXT CHECK (response_json IS NULL OR json_valid(response_json)),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    resolved_at INTEGER,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (requested_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (assigned_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (task_id, correlation_id)
);

CREATE INDEX idx_coordination_requests_inbox
    ON coordination_requests(task_id, assigned_session_id, status, blocking);

CREATE TABLE blockers (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    work_item_id TEXT NOT NULL,
    waits_for_type TEXT NOT NULL CHECK (length(waits_for_type) > 0),
    waits_for_id TEXT,
    status TEXT NOT NULL CHECK (status IN ('open', 'resolved', 'cancelled')),
    reason TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    resolution TEXT,
    opened_by_session_id TEXT NOT NULL,
    resolved_by_session_id TEXT,
    opened_at INTEGER NOT NULL,
    resolved_at INTEGER,
    FOREIGN KEY (work_item_id, task_id) REFERENCES work_items(id, task_id) ON DELETE CASCADE,
    FOREIGN KEY (opened_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (resolved_by_session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    CHECK (status <> 'resolved' OR (resolved_at IS NOT NULL AND resolution IS NOT NULL))
);

CREATE INDEX idx_blockers_item_open ON blockers(work_item_id, status);

CREATE TABLE artifacts (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    attempt_id TEXT,
    work_item_id TEXT,
    session_id TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (length(kind) > 0),
    value TEXT NOT NULL CHECK (length(value) > 0),
    digest TEXT,
    revision TEXT,
    metadata_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json)),
    created_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (attempt_id, task_id) REFERENCES work_attempts(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (work_item_id, task_id) REFERENCES work_items(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (session_id, task_id) REFERENCES agent_sessions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id)
);

CREATE INDEX idx_artifacts_item ON artifacts(work_item_id, created_at);

-- Add the evidence FKs that depend on artifacts/work_attempts now that both
-- parent tables exist. SQLite cannot add FK clauses after table creation, so
-- these relationships are additionally guarded by triggers.
CREATE TRIGGER validate_evidence_references_insert
BEFORE INSERT ON evidence
BEGIN
    SELECT CASE WHEN NEW.attempt_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM work_attempts a WHERE a.id = NEW.attempt_id AND a.task_id = NEW.task_id
    ) THEN RAISE(ABORT, 'evidence attempt belongs to another task or does not exist') END;
    SELECT CASE WHEN NEW.artifact_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM artifacts a WHERE a.id = NEW.artifact_id AND a.task_id = NEW.task_id
    ) THEN RAISE(ABORT, 'evidence artifact belongs to another task or does not exist') END;
END;

CREATE TRIGGER validate_evidence_references_update
BEFORE UPDATE OF task_id, attempt_id, artifact_id ON evidence
BEGIN
    SELECT CASE WHEN NEW.attempt_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM work_attempts a WHERE a.id = NEW.attempt_id AND a.task_id = NEW.task_id
    ) THEN RAISE(ABORT, 'evidence attempt belongs to another task or does not exist') END;
    SELECT CASE WHEN NEW.artifact_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM artifacts a WHERE a.id = NEW.artifact_id AND a.task_id = NEW.task_id
    ) THEN RAISE(ABORT, 'evidence artifact belongs to another task or does not exist') END;
END;

CREATE TABLE review_results (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    work_item_id TEXT NOT NULL,
    claim_id TEXT NOT NULL UNIQUE,
    decision TEXT NOT NULL CHECK (decision IN ('approved', 'changes_requested')),
    evidence_ids_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(evidence_ids_json)),
    created_at INTEGER NOT NULL,
    FOREIGN KEY (work_item_id, task_id) REFERENCES work_items(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (claim_id, task_id) REFERENCES work_claims(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id)
);

CREATE TABLE change_sets (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    attempt_id TEXT NOT NULL UNIQUE,
    base_commit TEXT NOT NULL CHECK (length(base_commit) > 0),
    head_commit TEXT NOT NULL CHECK (length(head_commit) > 0),
    changed_resources_json TEXT NOT NULL CHECK (json_valid(changed_resources_json)),
    tests_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tests_json)),
    integration_state TEXT NOT NULL CHECK (integration_state IN ('pending', 'integrating', 'integrated', 'superseded', 'failed')),
    integration_claim_id TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (attempt_id, task_id) REFERENCES work_attempts(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (integration_claim_id, task_id) REFERENCES work_claims(id, task_id) ON DELETE RESTRICT,
    UNIQUE (id, task_id)
);

CREATE INDEX idx_change_sets_task_integration ON change_sets(task_id, integration_state);

CREATE TABLE invalidations (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    source_type TEXT NOT NULL CHECK (length(source_type) > 0),
    source_id TEXT NOT NULL CHECK (length(source_id) > 0),
    target_type TEXT NOT NULL CHECK (length(target_type) > 0),
    target_id TEXT NOT NULL CHECK (length(target_id) > 0),
    old_revision TEXT,
    new_revision TEXT NOT NULL CHECK (length(new_revision) > 0),
    status TEXT NOT NULL CHECK (status IN ('open', 'resolved', 'superseded')),
    reason TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    created_at INTEGER NOT NULL,
    resolved_at INTEGER,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (id, task_id)
);

CREATE UNIQUE INDEX uq_invalidations_open_source_target
    ON invalidations(task_id, source_type, source_id, target_type, target_id)
    WHERE status = 'open';
CREATE INDEX idx_invalidations_target_open ON invalidations(task_id, target_type, target_id, status);

CREATE TABLE events (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    workspace_id TEXT NOT NULL,
    task_id TEXT,
    event_type TEXT NOT NULL CHECK (length(event_type) > 0),
    actor_type TEXT NOT NULL CHECK (length(actor_type) > 0),
    actor_id TEXT,
    entity_type TEXT NOT NULL CHECK (length(entity_type) > 0),
    entity_id TEXT,
    payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
    schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version >= 1),
    created_at INTEGER NOT NULL,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE RESTRICT
);

CREATE INDEX idx_events_task_sequence ON events(task_id, sequence);
CREATE INDEX idx_events_workspace_sequence ON events(workspace_id, sequence);

CREATE TABLE task_completions (
    id TEXT PRIMARY KEY CHECK (length(id) > 0),
    task_id TEXT NOT NULL,
    completion_epoch INTEGER NOT NULL CHECK (completion_epoch >= 1),
    completion_policy TEXT NOT NULL CHECK (completion_policy IN ('all_workers_concluded')),
    trigger_actor_type TEXT NOT NULL CHECK (length(trigger_actor_type) > 0),
    trigger_actor_id TEXT,
    conclusion_set_digest BLOB NOT NULL CHECK (length(conclusion_set_digest) = 32),
    snapshot_completion_revision INTEGER NOT NULL CHECK (snapshot_completion_revision >= 0),
    basis_event_cursor INTEGER NOT NULL CHECK (basis_event_cursor >= 0),
    basis_plan_version INTEGER NOT NULL CHECK (basis_plan_version >= 0),
    completion_event_sequence INTEGER NOT NULL UNIQUE,
    signal_snapshot_json TEXT NOT NULL CHECK (json_valid(signal_snapshot_json)),
    completed_at INTEGER NOT NULL,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE RESTRICT,
    FOREIGN KEY (completion_event_sequence) REFERENCES events(sequence) ON DELETE RESTRICT,
    UNIQUE (id, task_id),
    UNIQUE (task_id, completion_epoch)
);

CREATE TABLE task_completion_conclusions (
    task_completion_id TEXT NOT NULL,
    task_id TEXT NOT NULL,
    agent_conclusion_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    PRIMARY KEY (task_completion_id, agent_conclusion_id),
    FOREIGN KEY (task_completion_id, task_id) REFERENCES task_completions(id, task_id) ON DELETE RESTRICT,
    FOREIGN KEY (agent_conclusion_id, task_id) REFERENCES agent_conclusions(id, task_id) ON DELETE RESTRICT,
    UNIQUE (task_completion_id, ordinal)
);

CREATE TABLE task_completion_assurance_flags (
    task_completion_id TEXT NOT NULL,
    flag TEXT NOT NULL CHECK (flag IN ('single_agent_assurance', 'completed_with_warnings', 'retired_participant_assurance')),
    PRIMARY KEY (task_completion_id, flag),
    FOREIGN KEY (task_completion_id) REFERENCES task_completions(id) ON DELETE RESTRICT
);

CREATE TABLE idempotency_records (
    actor_type TEXT NOT NULL CHECK (length(actor_type) > 0),
    actor_id TEXT NOT NULL CHECK (length(actor_id) > 0),
    request_id TEXT NOT NULL CHECK (length(request_id) > 0),
    task_id TEXT,
    payload_hash BLOB NOT NULL CHECK (length(payload_hash) = 32),
    result_json TEXT NOT NULL CHECK (json_valid(result_json)),
    event_sequence INTEGER,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (actor_type, actor_id, request_id),
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE RESTRICT,
    FOREIGN KEY (event_sequence) REFERENCES events(sequence) ON DELETE RESTRICT
);

CREATE TRIGGER task_completions_immutable_update
BEFORE UPDATE ON task_completions
BEGIN
    SELECT RAISE(ABORT, 'task completions are immutable');
END;

CREATE TRIGGER task_completions_immutable_delete
BEFORE DELETE ON task_completions
BEGIN
    SELECT RAISE(ABORT, 'task completions are immutable');
END;

CREATE TRIGGER task_completion_conclusions_immutable_update
BEFORE UPDATE ON task_completion_conclusions
BEGIN
    SELECT RAISE(ABORT, 'task completion conclusion sets are immutable');
END;

CREATE TRIGGER task_completion_conclusions_immutable_delete
BEFORE DELETE ON task_completion_conclusions
BEGIN
    SELECT RAISE(ABORT, 'task completion conclusion sets are immutable');
END;

CREATE TRIGGER events_immutable_update
BEFORE UPDATE ON events
BEGIN
    SELECT RAISE(ABORT, 'events are immutable');
END;

CREATE TRIGGER events_immutable_delete
BEFORE DELETE ON events
BEGIN
    SELECT RAISE(ABORT, 'events are immutable');
END;
